starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "vpc_id" {
  description = "Input variable vpc_id."
  type        = string
}

variable "security_group_name" {
  description = "Input variable security_group_name."
  type        = string
  default     = "web-sg"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_security_group" "this" {
  # TODO - Complete the aws_security_group resource.
  # Add the arguments and nested blocks required for aws_security_group.
}
